#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}
# ──────────────────────────────────────────────────────────────────────────
# STAGES: provision Cloudflare R2 for services/recipes (ADR 0007).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# Everything this wizard writes holds or neighbours a secret access key, so
# nothing it creates is readable by anyone but the operator running it.
umask 077

# The staging file is deliberately outside the repo and outside /opt: the
# deploy directory is on the VPS and this wizard never SSHes anywhere, and a
# secret parked under infra/wizards/ would not be caught by .gitignore, whose
# .env rule matches the filename exactly. The operator copies it across at the
# end and deletes it.
ENV_FILE="${ENV_FILE:-${XDG_RUNTIME_DIR:-$HOME}/family-manager-r2.env}"

# _sha256_hex FILE|- → lowercase hex digest. Used for both the SigV4 payload
# hash and the canonical-request hash.
_sha256_hex() { openssl dgst -sha256 -r "$1" | cut -d' ' -f1; }

# _hmac_hex HEXKEY DATA → lowercase hex HMAC-SHA256. The SigV4 signing key is
# a four-deep HMAC chain, and every link but the first takes a binary key, so
# the key is threaded through as hex rather than as a shell string.
_hmac_hex() { printf '%s' "$2" | openssl dgst -sha256 -mac HMAC -macopt "hexkey:$1" -r | cut -d' ' -f1; }

# _sigv4_curl METHOD PATH BODY_FILE [CONTENT_TYPE] → runs curl against the R2
# S3 endpoint with an Authorization header we sign ourselves.
#
# This exists only as the last-resort validation path. aws/rclone are tried
# first because they don't put the secret anywhere a `ps` can see it, whereas
# openssl needs the derived key as an argv value. That's an acceptable leak on
# the operator's own laptop and not on a shared box — hence the ordering, not
# a refusal.
_sigv4_curl() {
  local method="$1" path="$2" body="$3" ctype="${4:-}"
  local host="$R2_ENDPOINT_HOST" region="auto" service="s3"
  local amzdate datestamp payload_hash
  amzdate=$(date -u +%Y%m%dT%H%M%SZ)
  datestamp=${amzdate%%T*}
  payload_hash=$(_sha256_hex "$body")

  local canonical_headers signed_headers
  canonical_headers="host:${host}
x-amz-content-sha256:${payload_hash}
x-amz-date:${amzdate}
"
  signed_headers="host;x-amz-content-sha256;x-amz-date"

  local canonical_request creq_hash scope string_to_sign
  canonical_request="${method}
${path}

${canonical_headers}
${signed_headers}
${payload_hash}"
  creq_hash=$(printf '%s' "$canonical_request" | _sha256_hex -)
  scope="${datestamp}/${region}/${service}/aws4_request"
  string_to_sign="AWS4-HMAC-SHA256
${amzdate}
${scope}
${creq_hash}"

  local k
  k=$(printf 'AWS4%s' "$R2_SECRET_ACCESS_KEY" | od -An -v -tx1 | tr -d ' \n')
  k=$(_hmac_hex "$k" "$datestamp")
  k=$(_hmac_hex "$k" "$region")
  k=$(_hmac_hex "$k" "$service")
  k=$(_hmac_hex "$k" "aws4_request")
  local signature
  signature=$(_hmac_hex "$k" "$string_to_sign")

  local auth="AWS4-HMAC-SHA256 Credential=${R2_ACCESS_KEY_ID}/${scope}, SignedHeaders=${signed_headers}, Signature=${signature}"
  local args=(-sS -o /dev/null -w '%{http_code}' -X "$method"
    -H "Host: ${host}" -H "x-amz-content-sha256: ${payload_hash}"
    -H "x-amz-date: ${amzdate}" -H "Authorization: ${auth}")
  [[ -n "$ctype" ]] && args+=(-H "Content-Type: ${ctype}")
  [[ "$method" == "PUT" ]] && args+=(--data-binary "@${body}")
  curl "${args[@]}" "https://${host}${path}"
}

banner "Cloudflare R2 setup for services/recipes"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Account ID"
say "Everything R2 is scoped to one Cloudflare account, and the S3 endpoint"
say "is derived from its ID — so this is the first value we need."
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "Open R2 Object Storage. The right-hand 'Account details' panel shows"
step "  'Account ID' — a 32-character hex string. Copy it."
note "It is also the first path segment of the dashboard URL:"
note "  dash.cloudflare.com/<ACCOUNT_ID>/r2/overview"
ask R2_ACCOUNT_ID "Paste the account ID:"

if [[ ! "$R2_ACCOUNT_ID" =~ ^[0-9a-f]{32}$ ]]; then
  warn "that doesn't look like a 32-char hex account ID; continuing anyway,"
  warn "but the round-trip test in stage 5 will fail if it's wrong."
fi

# minio-go takes a host, not a URL: libs/go/storage passes RECIPES_STORAGE_ENDPOINT
# straight to minio.New, and a scheme there is a construction error. TLS comes
# from RECIPES_STORAGE_USE_SSL instead.
R2_ENDPOINT_HOST="${R2_ACCOUNT_ID}.r2.cloudflarestorage.com"
say ""
say "Your S3 API endpoint is:"
printf '  %s%s%s\n' "$BOLD" "https://${R2_ENDPOINT_HOST}" "$RESET"
note "The service is configured with the bare host — no scheme — because"
note "minio-go wants a host and takes TLS from RECIPES_STORAGE_USE_SSL."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the bucket"
say "The bucket must exist before the service starts. The recipes service"
say "will NOT create it: R2 denies CreateBucket to an object-scoped token, so"
say "libs/go/storage makes EnsureBucket a no-op on the r2 provider (ADR 0007)."
warn "A missing bucket therefore doesn't fail at boot — it fails on the first"
warn "image upload, in production, silently. Get the name right here."
open_url "https://dash.cloudflare.com/?to=/:account/r2/new"
step "Click 'Create bucket'."
step "Name it to match RECIPES_STORAGE_BUCKET (default: recipes)."
step "Location: Automatic is fine. Storage class: Standard."
step "Create."
ask R2_BUCKET "Bucket name [recipes]:"
R2_BUCKET="${R2_BUCKET:-recipes}"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "API token — Object Read & Write, this bucket only"
say "R2 offers account-wide admin tokens and object-scoped ones. Take the"
say "object-scoped one, restricted to '${R2_BUCKET}'."
say ""
say "Why the scope matters:"
note "  Over-scoped (Admin, or all buckets): nothing breaks. The service works"
note "  fine. It's a blast-radius argument — this key sits in a plaintext .env"
note "  on a single VPS with root SSH open, and an admin token there can delete"
note "  every bucket in the account, not just the family's recipe photos."
note "  Under-scoped (Object Read only, or the wrong bucket): uploads fail with"
note "  403 at PutObject. The recipes handler degrades rather than crashing, so"
note "  you find out when someone tries to add a photo."
open_url "https://dash.cloudflare.com/?to=/:account/r2/api-tokens"
step "R2 → API → 'Manage API tokens' → 'Create API token'."
step "Permissions: select 'Object Read & Write'."
step "Specify bucket(s): 'Apply to specific buckets only' → ${R2_BUCKET}."
step "TTL: leave forever unless you have a rotation process that will renew it."
step "Create the token."
warn "The next screen is the only time the secret is ever shown. Don't close it."
say ""
step "Copy 'Access Key ID'."
ask R2_ACCESS_KEY_ID "Paste the access key ID:"
step "Copy 'Secret Access Key'. Input below is hidden and is never echoed back."
ask_secret R2_SECRET_ACCESS_KEY "Paste the secret access key:"

if [[ -z "$R2_ACCESS_KEY_ID" || -z "$R2_SECRET_ACCESS_KEY" ]]; then
  warn "both credentials are required — libs/go/storage refuses to construct a"
  warn "client without them. Re-run the wizard once you have them."
  exit 1
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Public read access"
say "The S3 endpoint from stage 1 serves NO public reads — every request there"
say "must be signed. But recipe image_url values are handed straight to an"
say "<Image> in the app with no signing round trip, so the bucket needs a"
say "public hostname in front of it. Without one, uploads succeed and every"
say "image 404s."
say ""
say "Two options:"
note "  r2.dev subdomain — one click, no DNS. Cloudflare rate-limits it and"
note "  documents it as non-production; it can't be cached or put behind a WAF,"
note "  and the hostname is a random pub-<hash>.r2.dev you can never move."
note "  Custom domain — needs the zone on Cloudflare and one DNS record, and"
note "  gives you caching, a stable name, and a host you can repoint later."
say ""
say "Recommended: a custom domain, e.g. img.nonamecat.pp.ua. The zone is"
say "already the one serving the four service subdomains, and image_url values"
say "are written into the database — a hostname you cannot move is a migration"
say "waiting to happen (ADR 0007 already flags exactly that cutover)."
open_url "https://dash.cloudflare.com/?to=/:account/r2/default/buckets/${R2_BUCKET}/settings"
step "Bucket → Settings → 'Public access'."
step "Custom domain (recommended): 'Custom Domains' → Add → enter the"
step "  hostname → review the CNAME → Connect Domain. Wait for Active."
step "Or r2.dev: 'Public Development URL' → Enable → type 'allow' → Allow."
step "Either way the dashboard now shows the exact public URL. Copy it."
warn "No trailing slash, and no bucket segment: an R2 public domain is bound"
warn "to one bucket, so libs/go/storage serves objects at <public>/<key>."
ask R2_PUBLIC_URL "Paste the public base URL (https://…):"

if [[ ! "$R2_PUBLIC_URL" =~ ^https:// ]]; then
  warn "expected an https:// URL — the app will not load images over http."
fi
R2_PUBLIC_URL="${R2_PUBLIC_URL%/}"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Validate: real upload, real public fetch"
say "Credentials that are only tested by the first production deploy are"
say "credentials you debug at 2am. We upload a small object with the token we"
say "just collected, fetch it back over the public URL, then delete it."

R2_TEST_KEY="_wizard-check/$(date -u +%Y%m%dT%H%M%SZ)-$$.txt"
R2_TEST_BODY=$(mktemp)
printf 'family-manager r2 wizard round trip\n' > "$R2_TEST_BODY"

UPLOAD_OK=0
UPLOAD_TOOL=""
if command -v aws >/dev/null 2>&1; then
  UPLOAD_TOOL="aws cli"
  say "using: aws cli"
  # Credentials go through the environment, never argv, so they don't show up
  # in the operator's process list or shell history.
  if AWS_ACCESS_KEY_ID="$R2_ACCESS_KEY_ID" \
     AWS_SECRET_ACCESS_KEY="$R2_SECRET_ACCESS_KEY" \
     AWS_DEFAULT_REGION=auto \
     AWS_REQUEST_CHECKSUM_CALCULATION=when_required \
     AWS_RESPONSE_CHECKSUM_VALIDATION=when_required \
     aws s3api put-object \
       --endpoint-url "https://${R2_ENDPOINT_HOST}" \
       --bucket "$R2_BUCKET" --key "$R2_TEST_KEY" \
       --body "$R2_TEST_BODY" --content-type text/plain >/dev/null 2>&1
  then UPLOAD_OK=1; fi
elif command -v rclone >/dev/null 2>&1; then
  UPLOAD_TOOL="rclone"
  say "using: rclone"
  if RCLONE_CONFIG=/dev/null \
     RCLONE_S3_PROVIDER=Cloudflare RCLONE_S3_REGION=auto \
     RCLONE_S3_ENDPOINT="https://${R2_ENDPOINT_HOST}" \
     RCLONE_S3_ACCESS_KEY_ID="$R2_ACCESS_KEY_ID" \
     RCLONE_S3_SECRET_ACCESS_KEY="$R2_SECRET_ACCESS_KEY" \
     rclone rcat ":s3:${R2_BUCKET}/${R2_TEST_KEY}" >/dev/null 2>&1 < "$R2_TEST_BODY"
  then UPLOAD_OK=1; fi
elif command -v openssl >/dev/null 2>&1 && command -v curl >/dev/null 2>&1; then
  UPLOAD_TOOL="curl + SigV4"
  say "using: curl with a hand-rolled SigV4 signature"
  code=$(_sigv4_curl PUT "/${R2_BUCKET}/${R2_TEST_KEY}" "$R2_TEST_BODY" "text/plain" || echo 000)
  if [[ "$code" == "200" ]]; then
    UPLOAD_OK=1
  else
    warn "PutObject returned HTTP ${code}"
    [[ "$code" == "403" ]] && warn "403 = the token can't write here: wrong bucket scope, or read-only."
    [[ "$code" == "404" ]] && warn "404 = bucket '${R2_BUCKET}' does not exist under this account."
  fi
fi

if [[ -z "$UPLOAD_TOOL" ]]; then
  warn "no aws cli, no rclone, and no openssl+curl — cannot test the upload."
  warn "The credentials are UNVERIFIED. Install one of them and re-run, or"
  warn "accept that the first failure will be a production image upload."
  SKIPPED+=("verify R2 credentials with a real upload (no signing tool available)")
elif (( UPLOAD_OK )); then
  printf '  %s✓%s upload succeeded (%s)\n' "$GREEN" "$RESET" "$UPLOAD_TOOL"

  # The upload proves the token. This proves the public hostname, which is the
  # half that silently 404s in production if the domain isn't Active yet.
  fetch_code=$(curl -sS -o /dev/null -w '%{http_code}' "${R2_PUBLIC_URL}/${R2_TEST_KEY}" || echo 000)
  if [[ "$fetch_code" == "200" ]]; then
    printf '  %s✓%s public fetch succeeded: %s/%s\n' "$GREEN" "$RESET" "$R2_PUBLIC_URL" "$R2_TEST_KEY"
  else
    warn "public fetch returned HTTP ${fetch_code} — the object uploaded fine,"
    warn "but ${R2_PUBLIC_URL} does not serve it. Usual causes:"
    note "  - the custom domain is still Initializing (wait, then re-run)"
    note "  - public access was never enabled on the bucket"
    note "  - the URL has a bucket segment in it; R2 public domains have none"
    SKIPPED+=("confirm public reads at ${R2_PUBLIC_URL} (fetch returned ${fetch_code})")
  fi

  # Clean up: leaving probe objects in a production bucket is how you end up
  # with a bucket nobody trusts. Best effort — a failure here is cosmetic.
  if [[ "$UPLOAD_TOOL" == "aws cli" ]]; then
    AWS_ACCESS_KEY_ID="$R2_ACCESS_KEY_ID" AWS_SECRET_ACCESS_KEY="$R2_SECRET_ACCESS_KEY" \
      AWS_DEFAULT_REGION=auto aws s3api delete-object \
      --endpoint-url "https://${R2_ENDPOINT_HOST}" \
      --bucket "$R2_BUCKET" --key "$R2_TEST_KEY" >/dev/null 2>&1 || true
  elif [[ "$UPLOAD_TOOL" == "rclone" ]]; then
    RCLONE_CONFIG=/dev/null RCLONE_S3_PROVIDER=Cloudflare RCLONE_S3_REGION=auto \
      RCLONE_S3_ENDPOINT="https://${R2_ENDPOINT_HOST}" \
      RCLONE_S3_ACCESS_KEY_ID="$R2_ACCESS_KEY_ID" \
      RCLONE_S3_SECRET_ACCESS_KEY="$R2_SECRET_ACCESS_KEY" \
      rclone deletefile ":s3:${R2_BUCKET}/${R2_TEST_KEY}" >/dev/null 2>&1 || true
  else
    _sigv4_curl DELETE "/${R2_BUCKET}/${R2_TEST_KEY}" /dev/null >/dev/null 2>&1 || true
  fi
  note "probe object deleted"
else
  warn "upload FAILED with ${UPLOAD_TOOL}. The env block below would deploy a"
  warn "service whose image uploads 403. Fix before deploying:"
  note "  - is the token scoped to bucket '${R2_BUCKET}' with Object Read & Write?"
  note "  - does bucket '${R2_BUCKET}' exist under account ${R2_ACCOUNT_ID}?"
  note "  - did the secret paste cleanly (no trailing newline or truncation)?"
  SKIPPED+=("re-run this wizard: the credential round trip failed")
fi
rm -f "$R2_TEST_BODY"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Write the env block"
say "Five keys, matching infra/.env.example."
note "docker-compose.prod.yml interpolates these into the recipes container as"
note "RECIPES_STORAGE_*. Do not also put RECIPES_STORAGE_* lines in .env: the"
note "compose environment: block wins, so those lines would look authoritative"
note "and change nothing — an operator editing the bucket there would restart"
note "and find it unchanged. One spelling per setting, and this is the one."

write_env R2_ENDPOINT          "$R2_ENDPOINT_HOST"
write_env R2_ACCESS_KEY_ID     "$R2_ACCESS_KEY_ID"
write_env R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"
write_env R2_BUCKET            "$R2_BUCKET"
write_env R2_PUBLIC_URL        "$R2_PUBLIC_URL"
chmod 600 "$ENV_FILE"

say ""
say "Append this to /opt/family-manager/.env on the VPS:"
printf '\n'
printf '    # Host only, no scheme, no bucket segment: minio-go wants a host, and TLS\n'
printf '    # comes from the compose file, not from this value.\n'
printf '    R2_ENDPOINT=%s\n' "$R2_ENDPOINT_HOST"
printf '    R2_ACCESS_KEY_ID=%s\n' "$R2_ACCESS_KEY_ID"
printf '    R2_SECRET_ACCESS_KEY=%s%s%s\n' "$DIM" "<hidden — copy the line from ${ENV_FILE}>" "$RESET"
printf '    R2_BUCKET=%s\n' "$R2_BUCKET"
printf '    # The public custom domain, with scheme. A DIFFERENT host from R2_ENDPOINT.\n'
printf '    R2_PUBLIC_URL=%s\n' "$R2_PUBLIC_URL"
printf '\n'
note "RECIPES_STORAGE_PROVIDER=r2 and RECIPES_STORAGE_USE_SSL=true are already"
note "literals in the compose file, so they are not yours to set here."
warn "The secret is deliberately not printed. It is in ${ENV_FILE} (mode 600)."
note "Transfer it without it landing in your shell history, e.g.:"
note "  scp ${ENV_FILE} root@79.108.160.103:/tmp/r2.env"
note "  ssh root@79.108.160.103 'cat /tmp/r2.env >> /opt/family-manager/.env \\"
note "    && rm /tmp/r2.env && chmod 600 /opt/family-manager/.env'"
say ""
if confirm "Delete the local ${ENV_FILE} now (say no until it's on the VPS)?"; then
  rm -f "$ENV_FILE"
  note "deleted — re-run the wizard if you need it again"
fi

SKIPPED+=("restart the recipes container so it picks up the new env")
SKIPPED+=("upload one recipe image end to end and confirm it renders in the app")

finish
